let active=(location.hash.slice(1)||'processes').split('?')[0];
let mobileOpen=false, modalSubmit=null, lastFocus=null, toastTimer;
const tone={ 'on-track':'green','at-risk':'amber','off-track':'red'};
const statusText={'on-track':'Dans la trajectoire','at-risk':'À surveiller','off-track':'En retard'};
const nowLabel=d=>{try{return new Date(d).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}catch{return ''}};
const action=(name,text,cls='',id='')=>`<button class="btn ${cls}" data-action="${name}" data-id="${esc(id)}">${text}</button>`;
function download(name,data){const b=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:'application/json'});const u=URL.createObjectURL(b);const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function renderOverview(s){
 const pending=[...getWorkflowInterventions(s).map(r=>({...r,type:'approval',priority:'high',isWorkflow:true})),...s.decisions.filter(d=>d.status==='pending')];const bots=s.agents.filter(a=>a.type==='agent');const live=bots.filter(a=>a.status==='active');const on=s.goals.filter(g=>g.status==='on-track');const risk=s.goals.length-on.length;const gaps=s.gaps.filter(g=>g.status==='open');const measured=bots.filter(a=>a.hours>0);const quality=measured.length?Math.round(measured.reduce((n,a)=>n+a.quality,0)/measured.length):0;const totalHours=s.agents.reduce((n,a)=>n+a.hours,0),agentHours=bots.reduce((n,a)=>n+a.hours,0);const recent=[...s.audit].sort((a,b)=>new Date(b.time)-new Date(a.time)).slice(0,4);
 return `<header class="page-head"><div><div class="eyebrow">LE CAP RESTE HUMAIN</div><h1 class="page-title">Votre organisation, en mouvement.</h1><p class="page-description">Bonjour ${esc((s.agents.find(a=>a.id===s.workspace?.actorId)?.name||'Matthieu').split(' ')[0])}. Voici ce qui avance, ce qui bloque et ce qui a besoin de vous.</p></div><div class="head-actions"><span class="period-select">${icon('clock',13)} Novembre 2026</span>${action('gov-new-goal',icon('plus',14)+' Définir un objectif','btn-primary')}</div></header>
 <section class="overview-brief"><div class="brief-symbol">${icon('activity',19)}</div><div class="brief-main"><div class="brief-title">Votre point de gouvernance <span>Synthèse des données de démonstration</span></div><p class="brief-copy">${risk?`<strong>${on.length} objectifs sur ${s.goals.length}</strong> suivent la trajectoire attendue. `:'Tous vos objectifs suivent la trajectoire attendue. '}<strong>${pending.length} décisions</strong> attendent un arbitrage${gaps.length?`, et ${gaps.length} points de blocage ont été identifiés`:''}. ${pending.length?'Votre intervention peut faire avancer les dossiers en attente.':'Votre équipe peut poursuivre son travail dans ses mandats.'}</p><div class="brief-actions"><button class="text-button" data-action="nav" data-value="decisions">Examiner les décisions ${icon('arrow',12)}</button><button class="text-button" data-action="nav" data-value="gaps">Comprendre les blocages ${icon('arrow',12)}</button></div></div></section>
 <section class="stat-grid"><div class="stat-card"><div class="stat-label">Objectifs dans la trajectoire ${icon('target')}</div><div class="stat-value">${on.length} <small>/ ${s.goals.length}</small></div><div class="stat-foot"><span class="positive">${icon('activity',12)}</span> ${risk} objectif${risk>1?'s':''} à accompagner</div></div><div class="stat-card"><div class="stat-label">Décisions à prendre ${icon('inbox')}</div><div class="stat-value">${pending.length.toString().padStart(2,'0')}</div><div class="stat-foot">${badge(pending.filter(d=>d.priority==='high').length+' prioritaires','amber')} Un responsable, une décision</div></div><div class="stat-card"><div class="stat-label">Agents en service ${icon('bot')}</div><div class="stat-value">${live.length.toString().padStart(2,'0')} <small>/ ${bots.length}</small></div><div class="stat-foot">${bots.filter(a=>a.status==='pilot').length} en pilote · ${bots.filter(a=>a.status==='paused').length} suspendu(s)</div></div><div class="stat-card"><div class="stat-label">Travail délégué aux agents ${icon('users')}</div><div class="stat-value">${Math.round(agentHours/Math.max(totalHours,1)*100)}<small> %</small></div><div class="stat-foot"><span class="positive">${quality}%</span> de qualité moyenne validée</div></div></section>
 <div class="overview-columns"><section class="card"><div class="card-head"><div><h2 class="card-title">Le cap de vos équipes</h2><p class="card-subtitle">Des objectifs partagés, des résultats visibles.</p></div><button class="text-button" data-action="nav" data-value="goals">Tout voir ${icon('arrow',12)}</button></div>${s.goals.slice(0,4).map(g=>`<div class="goal-line" role="button" tabindex="0" data-action="gov-goal-detail" data-id="${esc(g.id)}"><div class="goal-line-top"><span>${esc(g.title)}</span>${badge(statusText[g.status],tone[g.status])}</div><div class="goal-line-bottom">${progress(g.progress,tone[g.status])}<span class="percentage">${g.progress}%</span></div><div class="goal-meta">${esc(g.team)} <span>·</span> ${esc(g.owner)}</div></div>`).join('')}</section>
 <section class="card"><div class="card-head"><div><h2 class="card-title">Votre décision fait la différence</h2><p class="card-subtitle">Les exceptions qui vous reviennent.</p></div>${badge(pending.length+' en attente','amber')}</div>${pending.slice(0,3).map(d=>{const a=s.agents.find(a=>a.id===d.agentId);return `<div class="decision-preview" role="button" tabindex="0" data-action="${d.isWorkflow?'ws-open-run':'gov-decision-detail'}" data-id="${esc(d.id)}"><div class="icon-box ${d.type==='budget'?'purple':''}">${icon(d.type==='budget'?'sliders':'shield',16)}</div><div><strong>${esc(d.title)}</strong><p>${esc(a?.name||'Agent')} · ${esc(a?.team||'Organisation')}</p>${badge(d.priority==='high'?'Priorité haute':'Validation attendue',d.priority==='high'?'amber':'neutral')}</div><span class="icon-button">${icon('chevron',14)}</span></div>`}).join('')||empty('Tout est arbitré','Les prochaines demandes apparaîtront ici.')}${pending.length>3?`<div style="padding:13px 22px"><button class="text-button" data-action="nav" data-value="decisions">Voir les ${pending.length} décisions ${icon('arrow',12)}</button></div>`:''}</section></div>
 <div class="overview-columns activity-section"><section class="card"><div class="card-head"><div><h2 class="card-title">Les dernières décisions laissent une trace</h2><p class="card-subtitle">Le journal partagé de votre organisation.</p></div><button class="text-button" data-action="nav" data-value="audit">Journal ${icon('arrow',12)}</button></div><div class="activity-list">${recent.map(e=>`<div class="activity-item"><span class="activity-icon">${icon('check',12)}</span><div><p>${esc(e.action)}</p><small>${esc(e.actor)} · ${esc(e.detail).slice(0,88)}</small></div><time>${nowLabel(e.time)}</time></div>`).join('')}</div></section><section class="card"><div class="card-head"><div><h2 class="card-title">Un collectif, quatre équipes</h2><p class="card-subtitle">Humains et agents, sous un même mandat.</p></div><button class="text-button" data-action="nav" data-value="organization">Explorer ${icon('arrow',12)}</button></div>${['Opérations','Investissement','Conformité','Distribution'].map((t,i)=>{const list=s.agents.filter(a=>a.team===t);return `<div class="team-mini"><span class="avatar" style="background:${['#edf1f8','#f0ebfa','#eaf4ef','#f8f0e7'][i]}">${icon(['activity','target','shield','users'][i],14)}</span><div><strong>${t}</strong><small>${list.filter(a=>a.type==='human').length} humain(s) · ${list.filter(a=>a.type==='agent').length} agent(s)</small></div><span class="tag">${s.goals.filter(g=>g.team===t).length} objectif(s)</span></div>`}).join('')}</section></div>`;
}
function renderAudit(s){const cost=s.agents.filter(a=>a.type==='agent').reduce((n,a)=>n+a.cost,0);const budget=s.settings.budget||8000;const history=[...s.audit].sort((a,b)=>new Date(b.time)-new Date(a.time));return `<header class="page-head"><div><div class="eyebrow">PREUVES & RESSOURCES</div><h1 class="page-title">Chaque décision compte.</h1><p class="page-description">Retrouvez les arbitrages humains, leurs motifs et le coût des agents.</p></div><div class="head-actions">${action('export-audit',icon('download',14)+' Exporter le journal')}${action('edit-budget','Ajuster le budget','btn-primary')}</div></header><div class="stat-grid"><div class="stat-card"><div class="stat-label">Coût des agents</div><div class="stat-value">${money(cost)}</div><div class="stat-foot">Données fictives · novembre</div></div><div class="stat-card"><div class="stat-label">Budget mensuel</div><div class="stat-value">${money(budget)}</div><div class="stat-foot">${Math.round(cost/Math.max(budget,1)*100)} % consommés</div></div><div class="stat-card"><div class="stat-label">Décisions documentées</div><div class="stat-value">${s.decisions.filter(d=>d.status!=='pending').length}</div><div class="stat-foot">Approbations et refus humains</div></div><div class="stat-card"><div class="stat-label">Événements de gouvernance</div><div class="stat-value">${s.audit.length}</div><div class="stat-foot">Journal local, exportable</div></div></div><div class="grid-2"><section class="card pad"><div class="row between"><h2 class="card-title">Répartition des coûts</h2>${badge('Démonstration','neutral')}</div>${['Opérations','Investissement','Conformité','Distribution'].map(t=>{const c=s.agents.filter(a=>a.team===t&&a.type==='agent').reduce((n,a)=>n+a.cost,0);return `<div class="kr-row"><div class="row between"><strong>${t}</strong><span class="small">${money(c)}</span></div>${progress(c/Math.max(cost,1)*100)}</div>`}).join('')}</section><section class="card pad"><h2 class="card-title">La gouvernance en pratique</h2><div class="detail-grid"><div class="detail-item"><span>Règles actives</span><strong>${s.policies.filter(p=>p.enabled).length}</strong></div><div class="detail-item"><span>Mandats d’agents</span><strong>${s.agents.filter(a=>a.type==='agent').length}</strong></div><div class="detail-item"><span>Blocages résolus</span><strong>${s.gaps.filter(g=>g.status==='resolved').length}</strong></div><div class="detail-item"><span>Exécutions terminées</span><strong>${s.runs.filter(r=>r.status==='completed').length}</strong></div></div><div class="notice">${icon('info',17)}<p>Les coûts et résultats initiaux sont fictifs. Le journal reflète vos interactions dans ce navigateur ; il n’est pas un registre d’audit sécurisé.</p></div></section></div><section class="card" style="margin-top:22px"><div class="card-head"><h2 class="card-title">Historique des décisions et modifications</h2><span class="small muted">${history.length} événements</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Responsable</th><th>Action</th><th>Contexte</th></tr></thead><tbody>${history.map(e=>`<tr><td>${new Date(e.time).toLocaleString('fr-FR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}</td><td>${esc(e.actor)}</td><td>${esc(e.action)}</td><td style="white-space:normal;min-width:240px;max-width:450px;color:#96889f">${esc(e.detail)}</td></tr>`).join('')}</tbody></table></div></section>`}
const renderers={overview:renderOverview,goals:renderGoals,decisions:s=>renderInterventions(s,getWorkflowInterventions(s)),interventions:s=>renderInterventions(s,getWorkflowInterventions(s)),organization:renderTeams,agents:renderAgents,skills:renderSkills,workforce:renderWorkforce,transformation:renderTransformation,spend:renderSpend,security:renderSecurity,administration:renderAdministration,knowledge:renderKnowledge,workbench:renderWorkbench,mandates:renderMandates,gaps:renderGaps,processes:renderWorkflows,policies:renderPolicies,audit:renderAudit,integrations:renderConnections,engines:renderIntegrations};
let initializing=false;
function initExtensions(){if(initializing)return;initializing=true;try{initWorkflows();initCapabilities();initGovernancePlus();initWorkspace();}finally{initializing=false;}}
function richNav(id,label,ico,detail='',count=0){return `<a class="nav-item os-nav ${active===id?'active':''}" href="#${id}" ${active===id?'aria-current="page"':''}>${icon(ico,17)}<span><strong>${label}</strong>${detail?`<small>${esc(detail)}</small>`:''}</span>${count?`<b class="nav-count warm">${count}</b>`:''}</a>`;}
function renderSidebar(s){
 const pending=s.decisions.filter(d=>d.status==='pending'),studio=getWorkflowInterventions(s),gaps=s.gaps.filter(g=>g.status==='open'),actor=s.agents.find(a=>a.id===s.workspace.actorId),persona=currentPersona(s),mode=s.workspace.mode==='governance'?'governance':'teams';
 const processList=getWorkflowSidebar(s),hours=s.agents.filter(a=>a.type==='agent').reduce((n,a)=>n+a.hours,0);
 const attention=[...studio.map(r=>({id:r.id,title:r.title,detail:r.detail+' · '+r.owner,action:'ws-open-run'})),...pending.map(d=>({id:d.id,title:d.title,detail:(s.agents.find(a=>a.id===d.agentId)?.name||'Équipe')+' · '+(d.assignedTo||'À arbitrer'),action:'gov-decision-detail'}))];
 const teamNav=richNav('organization','Mon équipe','users',`${s.agents.filter(a=>a.type==='human').length} personnes · ${s.agents.filter(a=>a.type==='agent').length} agents`)+richNav('agents','Agents','bot',`${s.agents.filter(a=>a.status==='pilot').length} en qualification`)+richNav('processes','Processus','workflow',`${processList.length} processus · ${studio.length} attendent une décision`,studio.length)+`<div class="os-subnav">${processList.map(p=>`<button data-action="wf-open" data-id="${esc(p.id)}" title="${esc(p.name)}"><i class="${p.pending?'needs':''}"></i><span>${esc(p.name)}<small>${p.pending?p.pending+' intervention(s) attendue(s)':esc(p.detail)}</small></span></button>`).join('')}</div>`+richNav('skills','Compétences','target','Versions, tests et apprentissages')+richNav('integrations','Intégrations','plug','Applications & outils partagés')+richNav('knowledge','Sources partagées','inbox');
 const governanceNav=richNav('overview','Vue d’ensemble','grid')+richNav('goals','Objectifs','target',`${s.goals.length} objectifs · ${s.goals.filter(g=>g.status!=='on-track').length} à accompagner`)+`<div class="os-subnav goals">${s.goals.map(g=>`<button data-action="gov-goal-detail" data-id="${esc(g.id)}" title="${esc(g.title)}"><i class="${g.status==='on-track'?'good':'needs'}"></i><span>${esc(g.title)}<small>${esc(g.owner)} · ${g.krs.length} résultats clés</small></span></button>`).join('')}</div>`+richNav('gaps','Écarts à résoudre','alert',`${gaps.length} décisions à préparer`,gaps.length)+richNav('workforce','Organisation','users','Responsables & rattachements')+richNav('transformation','Transformation','activity','Phases, preuves & valeur')+richNav('policies','Politiques','shield','Bloquer, demander ou consigner')+richNav('security','Sécurité','lock')+richNav('spend','Dépenses & valeur','sliders')+richNav('administration','Administration','settings')+richNav('audit','Journal d’audit','history');
 return `<a href="#processes" class="brand" aria-label="Cousteau Governance — Accueil"><span class="brand-mark">C</span><span class="brand-name">COUSTEAU<small>GOVERNANCE</small></span></a><div class="workspace-switch"><span class="workspace-logo">N</span><div><strong>Northstar AM</strong><small>Organisation de démonstration</small></div></div><div class="os-modes" role="group" aria-label="Espaces de travail"><button data-action="os-mode" data-value="teams" class="${mode==='teams'?'selected':''}" aria-pressed="${mode==='teams'}">${icon('users',15)} Équipes</button><button data-action="os-mode" data-value="governance" class="${mode==='governance'?'selected':''}" aria-pressed="${mode==='governance'}">${icon('shield',15)} Gouvernance</button></div><div class="os-sidebar-scroll"><div class="os-attention"><button class="os-attention-title" data-action="nav" data-value="interventions"><span>${icon('inbox',15)} Besoin de vous</span><b>${attention.length}</b></button>${attention.slice(0,3).map(r=>`<button class="os-attention-item" data-action="${r.action}" data-id="${esc(r.id)}"><i></i><span><strong>${esc(r.title)}</strong><small>${esc(r.detail)}</small></span></button>`).join('')||'<p class="small muted">Aucune intervention en attente.</p>'}${attention.length>3?`<button class="os-view-all" data-action="nav" data-value="interventions">Voir les ${attention.length} interventions ${icon('arrow',12)}</button>`:''}</div><nav aria-label="${mode==='teams'?'Équipes':'Gouvernance'}">${mode==='teams'?teamNav:governanceNav}</nav></div><div class="sidebar-bottom"><div class="os-usage"><div><span>Heures agents · ce mois</span><b>${Math.round(hours)} / ${s.workspace.agentHoursLimit}</b></div>${progress(hours/s.workspace.agentHoursLimit*100)}</div><div class="profile"><button class="os-profile-button" data-action="ws-persona" aria-label="Changer de rôle">${avatar(actor||{name:'Matthieu Keip',type:'human',initials:'MK'})}<span><strong>${esc(actor?.name||'Matthieu Keip')}</strong><small>${esc(persona[1])}</small></span>${icon('chevron',12)}</button><button class="icon-button" data-action="settings" aria-label="Paramètres">${icon('settings',16)}</button></div></div>`;
}
let sidebarScroll=0,renderedMode='';
function render(){if(initializing)return;const sidebar=document.querySelector('.os-sidebar-scroll');if(sidebar)sidebarScroll=sidebar.scrollTop;initExtensions();if(!renderers[active])active='processes';const s=getState();const title=navs.find(n=>n[0]===active)?.[1]||'Cousteau Governance';const mobile=window.matchMedia('(max-width:700px)').matches;document.title=`${title} — Cousteau Governance`;const pending=s.decisions.filter(d=>d.status==='pending').length+getWorkflowInterventions(s).length;document.getElementById('app').innerHTML=`<div class="app-shell"><div class="mobile-shade ${mobileOpen?'open':''}" data-action="mobile-close"></div><aside class="sidebar ${mobileOpen?'open':''}" ${mobile&&!mobileOpen?'inert aria-hidden="true"':''} aria-label="Navigation principale">${renderSidebar(s)}</aside><div class="main-wrap"><header class="topbar"><div class="crumbs"><button class="icon-button mobile-toggle" data-action="mobile-toggle" aria-label="Ouvrir le menu">${icon('menu',18)}</button><span>Northstar AM</span>${icon('chevron',11)}<strong>${esc(title)}</strong></div><div class="top-actions"><button class="search-button" data-action="search" aria-label="Rechercher dans l’organisation">${icon('search',17)}<span>Rechercher</span><kbd>⌘ K</kbd></button><span class="live-label"><i></i> Simulation</span><button class="os-notification" data-action="nav" data-value="interventions" aria-label="${pending} interventions attendues">${icon('bell',17)}<b>${pending}</b></button></div></header><main class="content ${active==='processes'?'workflow-content':''}" id="main">${renderers[active](s)}<footer class="footer-note"><span>${icon('lock',11)} Scénario fictif · modifications conservées dans ce navigateur</span><span>Le cap reste humain</span></footer></main></div></div>`;const currentMode=s.workspace.mode;if(currentMode!==renderedMode)sidebarScroll=0;renderedMode=currentMode;document.querySelector('.os-sidebar-scroll').scrollTop=sidebarScroll;}
function toast(text){clearTimeout(toastTimer);const e=document.getElementById('toast');e.textContent=text;e.classList.add('show');toastTimer=setTimeout(()=>e.classList.remove('show'),3600)}
function navigate(view){closeDrawer();closeModal();mobileOpen=false;active=view;setModeForRoute(view);history.pushState(null,'','#'+view);render();window.scrollTo({top:0,behavior:'instant'})}
function syncOverlay(){document.body.classList.toggle('overlay-open',!!(document.getElementById('overlay').children.length||document.getElementById('drawer-root').children.length))}
function closeModal(){document.getElementById('overlay').innerHTML='';modalSubmit=null;syncOverlay();lastFocus?.focus?.()}
function closeDrawer(){document.getElementById('drawer-root').innerHTML='';syncOverlay()}
function modal({title,subtitle='',body,submitLabel='Enregistrer',onSubmit}){lastFocus=document.activeElement;modalSubmit=onSubmit;document.getElementById('overlay').innerHTML=`<div class="modal-backdrop" data-action="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><button class="icon-button" data-action="close-modal" aria-label="Fermer">${icon('x')}</button></div><form id="modal-form"><div class="modal-body">${body}</div><div class="modal-foot"><button class="btn" type="button" data-action="close-modal">Annuler</button><button class="btn btn-primary" type="submit">${esc(submitLabel)}</button></div></form></section></div>`;syncOverlay();setTimeout(()=>document.querySelector('#modal-form input,#modal-form textarea,#modal-form select')?.focus(),30)}
function drawer({title,subtitle='',body}){closeModal();document.getElementById('drawer-root').innerHTML=`<div class="drawer-backdrop" data-action="drawer-backdrop"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><div class="drawer-head"><div><h2 id="drawer-title">${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><button class="icon-button" data-action="close-drawer" aria-label="Fermer le détail">${icon('x')}</button></div><div class="drawer-body">${body}</div></section></div>`;syncOverlay();document.querySelector('.drawer .icon-button')?.focus()}
function setModeForRoute(view){const mode=teamRoutes.has(view)?'teams':['interventions','decisions'].includes(view)?getState().workspace?.mode:'governance';if(getState().workspace&&getState().workspace.mode!==mode)update(s=>s.workspace.mode=mode);}
const ctx={getState,update,simulateProcess,decide,setAutonomy,resolveGap,navigate,toast,render,modal,closeModal,drawer,closeDrawer,openWorkflow,openWorkflowRun};
function showSearch(){modal({title:'Retrouver le bon contexte',subtitle:'Objectifs, agents et processus de votre organisation.',submitLabel:'Fermer',body:'<div class="field"><label for="global-search">Rechercher</label><input type="search" id="global-search" placeholder="Un objectif, un agent, un processus…" autocomplete="off"></div><div id="search-results" class="search-results"></div>',onSubmit:()=>{}});searchResults('')}
function searchResults(q){const s=getState();const records=[...s.goals.map(g=>({name:g.title,type:'Objectif',id:g.id,action:'gov-goal-detail',icon:'target'})),...s.agents.map(a=>({name:a.name,type:a.role,id:a.id,action:'org-agent',icon:a.type==='agent'?'bot':'user'})),...getWorkflowSidebar(s).map(p=>({name:p.name,type:'Processus',id:p.id,action:'wf-open',icon:'workflow'})),...s.workspace.knowledge.map(d=>({name:d.name,type:'Source partagée',id:d.id,action:'ws-doc-detail',icon:'inbox'}))].filter(r=>(r.name+' '+r.type).toLowerCase().includes(q.toLowerCase())).slice(0,12);document.getElementById('search-results').innerHTML=records.map(r=>`<button type="button" class="search-result" data-action="${r.action}" data-id="${esc(r.id)}">${icon(r.icon,18)}<span>${esc(r.name)}<small>${esc(r.type)}</small></span></button>`).join('')||'<p class="muted small">Aucun résultat pour cette recherche.</p>'}
document.addEventListener('input',e=>{if(e.target.id==='global-search')searchResults(e.target.value)});
document.addEventListener('change',e=>handleWorkspaceFile(e,ctx));
document.addEventListener('submit',async e=>{if(e.target.id!=='modal-form')return;e.preventDefault();try{const r=await modalSubmit?.(new FormData(e.target));if(r!==false)closeModal()}catch(error){console.error(error);toast('La modification n’a pas pu être enregistrée.')}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if((a==='modal-backdrop'||a==='drawer-backdrop')&&e.target!==el)return;try{
 if(a==='os-mode'){update(s=>s.workspace.mode=el.dataset.value);return navigate(el.dataset.value==='teams'?'organization':'overview')}
 if(a==='ws-open-run')return openWorkflowRun(el.dataset.id,ctx);
 if(a==='org-process'){const p=getState().studio.processes.find(p=>p.id===el.dataset.id||p.legacyId===el.dataset.id);if(p)return openWorkflow(p.id,ctx)}
 if(a==='close-modal'||a==='modal-backdrop')return closeModal();if(a==='close-drawer'||a==='drawer-backdrop')return closeDrawer();if(a==='nav')return navigate(el.dataset.value);if(a==='mobile-toggle'){mobileOpen=!mobileOpen;return render()}if(a==='mobile-close'){mobileOpen=false;return render()}if(a==='search')return showSearch();if(a==='export-audit'){download('cousteau-governance-journal.json',getState().audit);return toast('Journal exporté.')}
 if(a==='export-workspace'){download('cousteau-governance-espace.json',exportState());return toast('Espace exporté.')}
 if(a==='edit-budget')return modal({title:'Budget mensuel des agents',subtitle:'Un plafond de pilotage pour votre espace de démonstration.',body:`<div class="field"><label for="budget">Budget mensuel en euros</label><input id="budget" name="budget" type="number" min="100" max="10000000" required value="${getState().settings.budget}"></div>`,onSubmit:fd=>{update(s=>s.settings.budget=Number(fd.get('budget')),'Budget ajusté',money(fd.get('budget')));toast('Budget mis à jour.')}});
 if(a==='settings')return drawer({title:'Votre espace de démonstration',subtitle:'Cousteau Governance · Version 2.0',body:`<div class="notice">${icon('info',18)}<p>Cette application utilise une organisation fictive. Vos modifications sont enregistrées sur cet appareil, dans ce navigateur.</p></div><h3>Ce que vous pouvez explorer</h3><p class="muted small">Concevoir des processus, publier une version, suivre les dossiers, arbitrer les interventions et piloter les équipes, compétences, écarts, politiques et coûts.</p><h3>Vos données de démonstration</h3><div class="stack">${action('export-workspace',icon('download',15)+' Exporter l’espace en JSON')}${action('reset-demo',icon('refresh',15)+' Réinitialiser la démonstration')}</div><h3>Connecter l’exécution</h3><p class="muted small">Les connecteurs Temporal et Mastra ne sont pas encore configurés. Leurs contrats cibles sont disponibles dans Intégrations.</p>${action('nav','Voir les intégrations','','')}`.replace('data-action="nav" data-id=""','data-action="nav" data-value="engines"')});
 if(a==='reset-demo'){closeDrawer();return modal({title:'Repartir du scénario initial',subtitle:'Vos modifications locales seront effacées.',body:'<p class="small muted">Les agents, objectifs, mandats et décisions retrouveront les données fictives de départ. Vous pouvez exporter votre espace avant de le réinitialiser.</p>',submitLabel:'Réinitialiser',onSubmit:()=>{resetState();toast('Le scénario initial est rétabli.')}})}
 if(handleWorkflows(a,el,ctx))return;if(handleTeams(a,el,ctx))return;if(handleCapabilities(a,el,ctx))return;if(handleGovernancePlus(a,el,ctx))return;if(handleWorkspace(a,el,ctx))return;if(handleOrganization(a,el,ctx))return;if(handleGovernance(a,el,ctx))return;
 }catch(error){console.error(error);toast('Cette action n’a pas pu aboutir. Réessayez.')}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();showSearch()}if(e.key==='Escape'){if(document.getElementById('overlay').children.length)closeModal();else closeDrawer();if(mobileOpen){mobileOpen=false;render()}}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"][data-action]')){e.preventDefault();e.target.click()}if(e.key==='Tab'){const box=document.querySelector('.modal')||document.querySelector('.drawer');if(box){const list=[...box.querySelectorAll('button,input,select,textarea,a[href],[tabindex="0"]')].filter(n=>!n.disabled&&n.offsetParent!==null);const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}}});
window.addEventListener('hashchange',()=>{active=(location.hash.slice(1)||'processes').split('?')[0];setModeForRoute(active);mobileOpen=false;closeDrawer();closeModal();render();window.scrollTo(0,0)});
initExtensions();setModeForRoute(active);subscribe(render);render();
